// lib/constants/directEmployers.ts
// Employers whose jobs are read straight from their own applicant tracking system (Greenhouse, Ashby, Lever) every day,
// so their apply links go to the employer and the site has all their published-salary jobs, not only the few a board
// re-posts. Asked by the owner (2026-11-09): "all jobs from OpenAI, Anthropic, SpaceX, xAI etc." and the AI employers
// listed on aijobs.ai. Each board was found by probing its public API on 2026-11-09 (job counts then, for scale);
// `slug` is the company's existing page on 6figjobs where it has one, so jobs join it instead of a duplicate company.
// Only jobs that publish a salary reaching the six-figure floor are kept (the normal ingest gate).
export type DirectEmployer = {
  slug: string
  name: string
  provider: 'greenhouse' | 'ashby' | 'lever' | 'workday'
  boardUrl: string
  /** The employer's own domain, for its logo; checked on 2026-11-09 to have a logo on logo.dev. */
  website?: string
}

